245.     /**
246.      * Normalize a model reference against the configured registry.
247.      * Throws for unknown models. When `requireQualified` is true, the caller
248.      * must provide the exact `provider:model` string rather than a bare alias.
249.      */
250.     normalizeModelRef(model?: string, options?: { requireQualified?: boolean }): string | undefined {
251.         const registry = this.workerDefaults.modelProviders;
252.         if (!registry) return model;
253. 
254.         const ref = model || registry.defaultModel;
255.         if (!ref) {
256.             if (model) {
257.                 throw new Error(
258.                     `Unknown model "${model}". Call list_available_models and choose an exact configured provider:model value.`,
259.                 );
260.             }
261.             throw new Error(
262.                 "No default model is configured. Set defaultModel in model_providers.json or specify an explicit provider:model when creating the session.",
263.             );
264.         }
265. 
266.         const normalized = registry.normalize(ref);
267.         if (!normalized) {
268.             throw new Error(
269.                 `Unknown model "${ref}". Call list_available_models and choose an exact configured provider:model value.`,
270.             );
271.         }
272.         if (options?.requireQualified && ref !== normalized) {
273.             throw new Error(
274.                 `Model "${ref}" is not allowed. Use the exact provider:model value returned by list_available_models, for example "${normalized}".`,
275.             );
276.         }
277.         return normalized;
278.     }
279. 
280.     resolveModelSwitchConfig(
281.         model: string,
282.         reasoningEffort?: import("./model-providers.js").ReasoningEffort | null,
283.     ): { model: string; reasoningEffort: import("./model-providers.js").ReasoningEffort | null } {
284.         const normalized = this.normalizeModelRef(model, { requireQualified: true });
285.         const registry = this.workerDefaults.modelProviders;
286.         const descriptor = registry?.getDescriptor(normalized);
287.         if (reasoningEffort) {
288.             const supported = descriptor?.supportedReasoningEfforts ?? [];
289.             if (!supported.includes(reasoningEffort)) {
290.                 throw new Error(`Model ${normalized} does not support reasoning effort '${reasoningEffort}'`);
291.             }
292.             return { model: normalized!, reasoningEffort };
293.         }
294.         return {
295.             model: normalized!,
296.             reasoningEffort: descriptor?.defaultReasoningEffort ?? null,
297.         };
298.     }
