300.     /**
301.      * Cached Copilot model catalogs for vision-capability lookups (5 min TTL),
302.      * keyed by client token key — capability entitlements are PER TOKEN
303.      * (per-user keys can differ from the deployment default), so one shared
304.      * cache would leak one identity's catalog onto another's sessions.
305.      */
306.     private modelCatalogCaches = new Map<string, { fetchedAt: number; models: Array<{ id: string; capabilities?: any }> }>();
